use wordcraft_engine::doc::{Document, Pos};
use wordcraft_engine::layout::DocLayout;
use wordcraft_engine::layout::hit::Caret;
use wordcraft_engine::render::{self, RenderOptions};
use wordcraft_engine::{CmdError, Region, Session, io, speech};

uniffi::setup_scaffolding!();

#[cfg(test)]
mod tests;

/// The smallest and largest raster scale, in pixels per point.
const MIN_SCALE: f32 = 0.05;
const MAX_SCALE: f32 = 12.0;

/// Characters typed on their own, one command each: AutoCorrect and AutoFormat run when one of
/// these is the whole of a `text.insert` (a keyboard may commit "word " at once), and smart quotes
/// when a quote is.
const TYPED_ALONE: &[char] = &[' ', ',', '.', ';', ':', '!', '?', '"', '\''];

/// What went wrong, as a message the user can act on.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    /// A command failed or was refused: unknown id, bad parameters, nothing to act on…
    #[error("{0}")]
    Command(String),
    /// A file could not be opened.
    #[error("{0}")]
    Open(String),
    /// The file is protected with a password and none was given.
    #[error("This document is protected with a password.")]
    NeedsPassword,
    /// The password given was wrong.
    #[error("The password isn't correct.")]
    WrongPassword,
    /// The document could not be written.
    #[error("{0}")]
    Save(String),
    /// There is no such page.
    #[error("There is no page {0}.")]
    NoPage(u32),
}

impl From<CmdError> for MobileError {
    fn from(e: CmdError) -> Self {
        MobileError::Command(e.to_string())
    }
}

