/// What the Styles list calls built-in style `name`: the comment styles go by their feature's
/// name, not the file's (`annotation text` is Comment Text).
fn style_display_name(name: &str) -> String {
    match name.to_ascii_lowercase().as_str() {
        "annotation reference" => "Comment Reference".into(),
        "annotation text" => "Comment Text".into(),
        "annotation subject" => "Comment Subject".into(),
        _ => name.to_string(),
    }
}

