/// The Shapes gallery's groups of presets (the Lines group's connectors are drawn by the app).
#[uniffi::export]
pub fn shape_gallery() -> Vec<ShapeGroup> {
    wordcraft_engine::doc::preset::GALLERY
        .iter()
        .map(|(name, presets)| ShapeGroup { name: (*name).to_string(), presets: presets.iter().map(|p| (*p).to_string()).collect() })
        .collect()
}

/// A preset's usual width over height: what it is first inserted at.
#[uniffi::export]
pub fn shape_aspect(preset: String) -> f32 {
    wordcraft_engine::doc::preset::aspect(&preset)
}

/// Preset `preset` drawn in a `width` × `height` frame (points or pixels), for the gallery's
/// icons; `None` for a preset the engine doesn't draw.
#[uniffi::export]
pub fn shape_outline(preset: String, width: f32, height: f32) -> Option<ShapeOutline> {
    use wordcraft_engine::doc::preset::{Shade, outline};
    let fit = |v: f32| if v.is_finite() { v.clamp(0.0, 10_000.0) } else { 0.0 };
    let o = outline(&preset, fit(width), fit(height), &[])?;
    let flat = |pts: &[[f32; 2]]| pts.iter().flatten().copied().collect::<Vec<f32>>();
    let lift = |s: Shade| match s {
        Shade::Lighten => 0.4,
        Shade::LightenLess => 0.2,
        Shade::Darken => -0.4,
        Shade::DarkenLess => -0.2,
    };
    Some(ShapeOutline {
        fill: o.fill.iter().map(|r| flat(r)).collect(),
        faces: o.faces.iter().map(|(s, r)| ShapeFace { lift: lift(*s), pts: flat(r) }).collect(),
        lines: o.lines.iter().map(|r| flat(r)).collect(),
        stroke_fill: o.stroke_fill,
        line_like: wordcraft_engine::doc::preset::line_like(&preset),
    })
}

/// The engine session for one app process.
#[derive(uniffi::Object)]
pub struct MobileSession {
    session: Mutex<Session>,
    /// The sentences Read Aloud is speaking (the app's own speech plays them one by one).
    reading: Mutex<Vec<speech::Utterance>>,
}

impl Default for MobileSession {
    fn default() -> Self {
        let mut s = Session::new(wordcraft_engine::blank_document(&Region::default()));
        // the app speaks each sentence with the phone's own speech and asks for the next
        s.read_aloud.backend = speech::Backend::Hold;
        // the phone app marks spelling (repeated words among it) but no grammar
        s.prefs.mark_grammar = false;
        Self { session: Mutex::new(s), reading: Mutex::new(Vec::new()) }
    }
}

impl MobileSession {
    /// The session, even when a call panicked while holding it: the engine keeps itself
    /// consistent between commands, and losing the user's document would be worse.
    fn lock(&self) -> MutexGuard<'_, Session> {
        self.session.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// The document and its layout, to draw from without holding the session (blocks are shared,
    /// so the copy is cheap), and how to draw them.
    fn snapshot(&self) -> (Document, Arc<DocLayout>, RenderOptions) {
        let mut s = self.lock();
        let layout = s.layout();
        let opts = render_options(&s);
        (s.doc.clone(), layout, opts)
    }

    fn run(s: &mut Session, id: &str, params: Value) -> Result<Value, MobileError> {
        Ok(s.run(id, &params)?)
    }

    /// Typing in the equation being edited: text goes in as the equation builds it up (a space
    /// or an operator after a fraction or a script), Enter breaks the line and Tab goes to the
    /// next place to type.
    fn type_in_equation(s: &mut Session, text: &str) -> Result<(), MobileError> {
        let mut pending = String::new();
        for ch in text.chars() {
            let key = match ch {
                '\r' => continue,
                '\n' => ("equation.enter", json!({})),
                '\t' => ("equation.move", json!({ "dir": "next" })),
                c => {
                    pending.push(c);
                    continue;
                }
            };
            if !pending.is_empty() {
                Self::run(s, "equation.type", json!({ "text": std::mem::take(&mut pending) }))?;
            }
            Self::run(s, key.0, key.1)?;
        }
        if !pending.is_empty() {
            Self::run(s, "equation.type", json!({ "text": pending }))?;
        }
        Ok(())
    }
}

#[uniffi::export]
impl MobileSession {
    #[uniffi::constructor]
    pub fn new() -> Arc<Self> {
        Arc::new(Self::default())
    }

    /// Start up with the phone's language and region (a BCP 47 tag such as `en-US`): new
    /// documents get its paper size, and the font folders are scanned in the background so the
    /// first page doesn't wait for them.
    pub fn start(&self, locale: String) {
        let region = Region::from_tag(&locale);
        wordcraft_engine::set_system_locale(&locale);
        self.lock().system_region = region;
        wordcraft_fonts::FontDb::global().scan_in_background();
    }

    /// Open the document at `path` (docx, doc, rtf, odt, txt…; the extension or the content
    /// decides). The app copies a document it was given by URI into its own folder first.
    pub fn open(&self, path: String, password: Option<String>) -> Result<DocumentInfo, MobileError> {
        let mut s = self.lock();
        let mut params = json!({ "path": path });
        if let (Some(p), Some(o)) = (password, params.as_object_mut()) {
            o.insert("password".into(), json!(p));
        }
        s.run("file.open", &params).map_err(|e| open_error(&e))?;
        Ok(info(&mut s))
    }

    /// The check box, list or date control at the caret, which a tap fills in (`None` elsewhere,
    /// and in other kinds of control).
    pub fn form_control(&self) -> Option<FormControl> {
        let r = probe(&mut self.lock(), "developer.control", &json!({}))?;
        let kind = r.get("type").and_then(Value::as_str)?;
        if !matches!(kind, "checkBox" | "dropDown" | "comboBox" | "date") {
            return None;
        }
        let str_of = |k: &str| r.get(k).and_then(Value::as_str).unwrap_or("").to_string();
        let items: Vec<(String, String)> = r
            .get("items")
            .and_then(Value::as_array)
            .map(|a| a.iter().filter_map(|i| Some((i.get("display")?.as_str()?.to_string(), i.get("value")?.as_str()?.to_string()))).collect())
            .unwrap_or_default();
        let (value, text) = (str_of("value"), str_of("text"));
        let chosen = items.iter().position(|(d, v)| (!value.is_empty() && *v == value) || (!text.is_empty() && *d == text));
        Some(FormControl {
            kind: kind.to_string(),
            title: str_of("title"),
            checked: r.get("checked").and_then(Value::as_bool).unwrap_or(false),
            items: items.into_iter().map(|(d, _)| d).collect(),
            chosen: chosen.and_then(|i| i32::try_from(i).ok()).unwrap_or(-1),
            date: str_of("date"),
            locked: r.get("lockEdit").and_then(Value::as_bool).unwrap_or(false),
        })
    }

    /// When the file at `path` is plain text (`.txt`) that isn't Unicode, so its encoding is a
    /// guess: the encodings it can be opened in and the one it is read in. `None` for any other
    /// file, which opens as it is.
    pub fn text_encoding_offer(&self, path: String) -> Option<TextEncodingOffer> {
        let ext = std::path::Path::new(&path).extension().and_then(|e| e.to_str()).unwrap_or("").to_ascii_lowercase();
        if !matches!(ext.as_str(), "txt" | "text") {
            return None;
        }
        let r = probe(&mut self.lock(), "file.textEncoding", &json!({ "path": path, "chars": 0 }))?;
        if r.get("guessed").and_then(Value::as_bool) != Some(true) {
            return None;
        }
        let encodings = r
            .get("encodings")
            .and_then(Value::as_array)?
            .iter()
            .filter_map(|e| Some(NamedChoice { id: e.get("label")?.as_str()?.to_string(), name: e.get("name")?.as_str()?.to_string() }))
            .collect();
        Some(TextEncodingOffer { detected: r.get("detected").and_then(Value::as_str)?.to_string(), encodings })
    }

    /// The start of the text file at `path` read in encoding `label`: the encoding picker's
    /// preview (empty when it can't be read).
    pub fn text_preview(&self, path: String, label: String) -> String {
        let mut s = self.lock();
        s.run("file.textEncoding", &json!({ "path": path, "encoding": label, "chars": 3000 }))
            .ok()
            .and_then(|r| r.get("preview").and_then(Value::as_str).map(str::to_string))
            .unwrap_or_default()
    }

    /// Open the plain-text file at `path` read in encoding `label`.
    pub fn open_text(&self, path: String, label: String) -> Result<DocumentInfo, MobileError> {
        let mut s = self.lock();
        s.run("file.open", &json!({ "path": path, "encoding": label })).map_err(|e| open_error(&e))?;
        Ok(info(&mut s))
    }

    /// A new document: `blank`, or one of the engine's templates (`sample`, `letter`, `resume`,
    /// `report`).
    pub fn new_document(&self, template: String) -> Result<DocumentInfo, MobileError> {
        let mut s = self.lock();
        let params = if template.is_empty() || template == "blank" { json!({}) } else { json!({ "template": template }) };
        Self::run(&mut s, "file.new", params)?;
        Ok(info(&mut s))
    }

    /// The document's pages, revision and undo state.
    pub fn document_info(&self) -> DocumentInfo {
        info(&mut self.lock())
    }

    /// Draw page `page` (0-based) at `scale` pixels per point.
    pub fn render_page(&self, page: u32, scale: f32) -> Result<PageImage, MobileError> {
        let (doc, layout, opts) = self.snapshot();
        let p = layout.pages.get(page as usize).ok_or(MobileError::NoPage(page + 1))?;
        let r = render::render_page(&doc, p, clamp_scale(scale), &opts);
        Ok(PageImage { width: r.width, height: r.height, rgba: r.pixels })
    }

    /// Draw the part of page `page` from (`x`, `y`), `width` × `height` points, at `scale`
    /// pixels per point: a tile of a zoomed-in page.
    pub fn render_area(&self, page: u32, x: f32, y: f32, width: f32, height: f32, scale: f32) -> Result<PageImage, MobileError> {
        let (doc, layout, opts) = self.snapshot();
        let p = layout.pages.get(page as usize).ok_or(MobileError::NoPage(page + 1))?;
        let finite = |v: f32| if v.is_finite() { v } else { 0.0 };
        let r = render::render_area(&doc, p, finite(x), finite(y), finite(width).max(0.0), finite(height).max(0.0), clamp_scale(scale), &opts);
        Ok(PageImage { width: r.width, height: r.height, rgba: r.pixels })
    }

    /// Run the engine command `id` with `params` (a JSON object; empty means `{}`) and return its
    /// result as JSON.
    pub fn execute(&self, id: String, params: String) -> Result<String, MobileError> {
        let params: Value = if params.trim().is_empty() {
            json!({})
        } else {
            serde_json::from_str(&params).map_err(|e| MobileError::Command(format!("{id}: parameters are not JSON: {e}")))?
        };
        let mut s = self.lock();
        // the keys' commands move and edit inside the equation being edited
        let (id, params) = match equation_key(&s, &id) {
            Some((eq, p)) => (eq.to_string(), p),
            None => (id, params),
        };
        let out = Self::run(&mut s, &id, params)?;
        Ok(out.to_string())
    }

    /// Whether the command `id` can run now (`None`), or why not.
    pub fn disabled_reason(&self, id: String) -> Option<String> {
        let s = self.lock();
        match s.registry.get(&id) {
            Some(spec) => (spec.enabled)(&s).map(str::to_string),
            None => Some(format!("unknown command {id}")),
        }
    }

    /// Put the caret at the point (`x`, `y`) of page `page`, or extend the selection to it. A tap
    /// on a picture or shape selects it instead.
    pub fn tap(&self, page: u32, x: f32, y: f32, extend: bool) -> Result<(), MobileError> {
        let mut s = self.lock();
        if !extend {
            let layout = s.layout();
            let story = s.sel.focus.story;
            let pg = page as usize;
            // on a phone the first tap on a shape selects it, text box or not (the desktop's
            // click goes into a text box's text); a tap in the text of the shape being edited
            // stays in the text
            let hit = layout
                .object_at_in(pg, x, y, 4.0, story)
                .or_else(|| layout.object_at(pg, x, y, 4.0))
                .or_else(|| layout.find_object(pg, |o| o.page == pg && o.rect.contains(o.unspin(x, y))))
                .filter(|o| o.text_box.is_none_or(|id| story != wordcraft_engine::doc::StoryRef::Part(id)));
            if let Some(o) = hit {
                let anchor = Pos::new(o.story, o.path.clone(), o.off);
                let focus = Pos::new(o.story, o.path, o.off + wordcraft_engine::doc::para::OBJ.len_utf8());
                s.page_hint = page as usize;
                s.sel = wordcraft_engine::Selection { anchor, focus };
                return Ok(());
            }
        }
        // a tap on other text (the body from a note, a note from the body) goes into that text
        // a tap in an equation puts the caret in it there, to type in
        if !extend && let Some((at, inner)) = s.layout().equation_hit(page as usize, x, y, s.sel.focus.story) {
            s.sel = wordcraft_engine::Selection::caret(at);
            s.page_hint = page as usize;
            Self::run(&mut s, "equation.edit", json!({ "pos": serde_json::to_value(&inner).unwrap_or(Value::Null) }))?;
            return Ok(());
        }
        let mut at = json!({ "page": page, "x": x, "y": y, "extend": extend });
        if !extend
            && let Some(story) = s.layout().story_at(page as usize, x, y).filter(|st| *st != s.sel.focus.story)
            && let Some(o) = at.as_object_mut()
        {
            o.insert("story".into(), serde_json::to_value(story).unwrap_or(Value::Null));
        }
        Self::run(&mut s, "caret.set", at)?;
        Ok(())
    }

    /// A hardware keyboard's shortcut (`Mod+B`, `Mod+Shift+Z`, `Alt+…`: the desktop's key names)
    /// through the document's key map. Returns whether a command was bound and ran.
    pub fn run_shortcut(&self, combo: String) -> Result<bool, MobileError> {
        let mut s = self.lock();
        let Some(id) = s.keymap.resolve(&s.registry, &combo).map(|spec| spec.id.to_string()) else { return Ok(false) };
        Self::run(&mut s, &id, json!({}))?;
        Ok(true)
    }

    /// Put the caret in the selected shape's text (Edit Text), when it has a text box. Returns
    /// whether it did.
    pub fn edit_object_text(&self) -> bool {
        let mut s = self.lock();
        let layout = s.layout();
        let hint = s.page_hint;
        let Some((pos, _)) = wordcraft_engine::cmd::objects::object_selection(&s) else { return false };
        let Some(id) = layout.find_object(hint, |o| o.story == pos.story && o.path == pos.path && o.off == pos.off).and_then(|o| o.text_box) else {
            return false;
        };
        let start = Pos::new(wordcraft_engine::doc::StoryRef::Part(id), wordcraft_engine::doc::Path(vec![0]), 0);
        let start = s.doc.clamp(&start);
        s.sel = wordcraft_engine::Selection { anchor: start.clone(), focus: start };
        true
    }

    /// Move one end of the selection (`anchor` or `focus`) to the point (`x`, `y`) of page
    /// `page`, the other end staying put: dragging a selection handle.
    pub fn set_selection_end(&self, end: String, page: u32, x: f32, y: f32) -> Result<(), MobileError> {
        let mut s = self.lock();
        if end == "anchor" {
            let focus = s.sel.focus.clone();
            Self::run(&mut s, "caret.set", json!({ "page": page, "x": x, "y": y }))?;
            let anchor = s.sel.focus.clone();
            s.sel = wordcraft_engine::Selection { anchor, focus };
        } else {
            Self::run(&mut s, "caret.set", json!({ "page": page, "x": x, "y": y, "extend": true }))?;
        }
        Ok(())
    }

    /// Select the word (`unit` = `word`), sentence or paragraph at the point (`x`, `y`) of page
    /// `page`: a double tap, a long press.
    pub fn select_at(&self, page: u32, x: f32, y: f32, unit: String) -> Result<(), MobileError> {
        let mut s = self.lock();
        Self::run(&mut s, "caret.set", json!({ "page": page, "x": x, "y": y }))?;
        let id = match unit.as_str() {
            "sentence" => "select.sentence",
            "paragraph" => "select.paragraph",
            _ => "select.word",
        };
        Self::run(&mut s, id, json!({}))?;
        Ok(())
    }

    /// The caret, the selection's other end and the highlighted rectangles.
    pub fn selection_view(&self) -> SelectionView {
        let mut s = self.lock();
        let layout = s.layout();
        let hint = s.page_hint;
        let sel = s.sel_ends().clone();
        // in the equation being edited: the caret at its place in the equation, and its shading
        let math = s.math.as_ref().and_then(|m| {
            let (pi, ex, base, ml) = layout.equation_geom(&m.at, hint)?;
            let zone = PageRect {
                page: page_index(pi),
                x: ex - 2.0,
                y: base - ml.ascent - 2.0,
                width: ml.width + 4.0,
                height: ml.ascent + ml.descent + 4.0,
            };
            let caret = ml.slot(&m.pos.path, m.pos.off).map(|slot| CaretBox {
                page: page_index(pi),
                x: ex + slot.x,
                top: base - slot.y - slot.a,
                height: slot.a + slot.d,
                width: 0.0,
            });
            Some((zone, caret))
        });
        if let Some((zone, caret)) = math {
            return SelectionView { collapsed: true, focus: caret, anchor: caret, rects: Vec::new(), object_frame: None, equation: Some(zone) };
        }
        let focus = layout.caret_on(&sel.focus, hint).map(caret_box);
        let anchor = layout.caret_on(&sel.anchor, hint).map(caret_box);
        let rects = if let Some(range) = s.cell_range() {
            table_mouse::cell_rects(&layout, &s.doc, range)
        } else if sel.is_collapsed() {
            Vec::new()
        } else {
            let (a, b) = sel.ordered();
            table_mouse::selection_rects(&layout, &s.doc, &a, &b, hint)
        };
        let rects = rects.into_iter().map(|(page, r)| PageRect { page: page_index(page), x: r.x, y: r.y, width: r.w, height: r.h }).collect();
        let object_frame = wordcraft_engine::cmd::objects::object_selection(&s).and_then(|(pos, _)| {
            layout.find_object(hint, |o| o.story == pos.story && o.path == pos.path && o.off == pos.off).map(|o| PageRect {
                page: page_index(o.page),
                x: o.rect.x,
                y: o.rect.y,
                width: o.rect.w,
                height: o.rect.h,
            })
        });
        SelectionView { collapsed: sel.is_collapsed(), focus, anchor, rects, object_frame, equation: None }
    }

    /// Type `text` at the caret (replacing the selection) as the keyboard committed it. A new line
    /// starts a paragraph and a tab is a tab; spaces, punctuation and quotes go in on their own so
    /// AutoCorrect, AutoFormat and smart quotes run as they do for keys typed one at a time.
    pub fn type_text(&self, text: String) -> Result<(), MobileError> {
        let mut s = self.lock();
        if s.math.is_some() {
            return Self::type_in_equation(&mut s, &text);
        }
        let mut pending = String::new();
        let flush = |s: &mut Session, pending: &mut String| -> Result<(), MobileError> {
            if !pending.is_empty() {
                Self::run(s, "text.insert", json!({ "text": std::mem::take(pending) }))?;
            }
            Ok(())
        };
        for ch in text.chars() {
            match ch {
                '\r' => {}
                '\n' => {
                    flush(&mut s, &mut pending)?;
                    Self::run(&mut s, "text.newParagraph", json!({}))?;
                }
                '\t' => {
                    flush(&mut s, &mut pending)?;
                    Self::run(&mut s, "text.tab", json!({}))?;
                }
                c if TYPED_ALONE.contains(&c) => {
                    flush(&mut s, &mut pending)?;
                    Self::run(&mut s, "text.insert", json!({ "text": c.to_string() }))?;
                }
                c => pending.push(c),
            }
        }
        flush(&mut s, &mut pending)
    }

    /// Delete `before` characters before the caret and `after` after it (the selection instead,
    /// when there is one, for the first of them): the keyboard's Backspace and its corrections.
    /// In an equation being edited, that equation's Backspace and Delete.
    pub fn delete_around(&self, before: u32, after: u32) -> Result<(), MobileError> {
        let mut s = self.lock();
        let (back, fwd) = if s.math.is_some() { ("equation.backspace", "equation.delete") } else { ("text.backspace", "text.delete") };
        for _ in 0..before.min(10_000) {
            Self::run(&mut s, back, json!({}))?;
        }
        for _ in 0..after.min(10_000) {
            Self::run(&mut s, fwd, json!({}))?;
        }
        Ok(())
    }

    /// Up to `before` UTF-16 units of the selection's paragraph before it, the selected text when
    /// it lies in one paragraph, and up to `after` units after it.
    pub fn text_around(&self, before: u32, after: u32) -> TextAround {
        let s = self.lock();
        // the paragraph's text isn't what's typed in an equation: nothing for the keyboard to correct
        if s.math.is_some() {
            return TextAround { before: String::new(), selected: String::new(), after: String::new() };
        }
        let (a, b) = s.sel_ends().ordered();
        let text_of = |p: &Pos| s.doc.para_at(p).map(|para| para.text.clone()).unwrap_or_default();
        let start_text = text_of(&a);
        let head = start_text.get(..a.off).unwrap_or_default();
        let same_para = a.story == b.story && a.path == b.path;
        let selected = if same_para { start_text.get(a.off..b.off).unwrap_or_default().to_string() } else { String::new() };
        let end_text = if same_para { start_text.clone() } else { text_of(&b) };
        let tail = end_text.get(b.off..).unwrap_or_default();
        TextAround { before: last_utf16(head, before as usize), selected, after: first_utf16(tail, after as usize) }
    }

    /// Show the document as pages (`print`) or reflowed to `width` points as one long page
    /// (`mobile`, the engine's Web Layout), and return the new pages.
    pub fn set_view(&self, mode: String, width: f32) -> Result<DocumentInfo, MobileError> {
        let mut s = self.lock();
        s.view.mobile = mode == "mobile";
        if mode == "mobile" {
            s.view.web_width = if width.is_finite() { width.clamp(72.0, 4000.0) } else { 360.0 };
            Self::run(&mut s, "view.webLayout", json!({}))?;
            // the width alone doesn't change the document: lay it out again
            s.relayout();
        } else {
            Self::run(&mut s, "view.printLayout", json!({}))?;
        }
        Ok(info(&mut s))
    }

    /// Whether the body holds drawings Mobile View moves from where the pages have them (ones
    /// the text wraps round, beside or above and below) or ink: Mobile View then says it can't
    /// show them as the pages do, as the reference says it for such documents (not for pictures
    /// in line with the text, or in front of it or behind it).
    pub fn has_drawings(&self) -> bool {
        use wordcraft_engine::doc::para::{OBJ, Wrap};
        let moved = |o: &wordcraft_engine::doc::InlineObject| {
            o.ink().is_some() || o.frame().is_some_and(|(_, _, f)| matches!(f.wrap, Wrap::Square | Wrap::Tight | Wrap::Through | Wrap::TopAndBottom))
        };
        let s = self.lock();
        s.doc.para_paths(wordcraft_engine::doc::StoryRef::Body).iter().any(|path| {
            s.doc
                .para_at(&Pos::new(wordcraft_engine::doc::StoryRef::Body, path.clone(), 0))
                .is_some_and(|p| p.text.char_indices().any(|(i, c)| c == OBJ && p.object_at(i).is_some_and(|o| o.is_drawing() && moved(o))))
        })
    }

    /// The zoom the document was saved at (View › Zoom), percent, which the pages first show at
    /// (as the reference opens them); 0 when it was saved fitting the page to the window.
    pub fn document_zoom(&self) -> u32 {
        match self.lock().doc.settings.zoom {
            Some(z) if z.fit.is_some() => 0,
            Some(z) => z.percent.clamp(10, 500),
            None => 100,
        }
    }

    /// How far down the first page its text starts (its top margin), points: the pages open
    /// scrolled past it, as the reference opens them.
    pub fn first_text_top(&self) -> f32 {
        let s = self.lock();
        s.doc.sections().first().map_or(0.0, |(_, sp)| if sp.margin_top.is_finite() { sp.margin_top.abs() } else { 0.0 })
    }

    /// Draw the pages dark (lightness inverted, pictures as they are) to sit in a dark theme.
    pub fn set_dark(&self, dark: bool) {
        self.lock().view.dark_mode = dark;
    }

    /// Where Find's matches are after a search or a step (see [`FindView`]).
    pub fn find_view(&self) -> FindView {
        let mut s = self.lock();
        let layout = s.layout();
        let hint = s.page_hint;
        let (a, b) = s.sel.ordered();
        let (a, b) = (a.clone(), b.clone());
        let results = &s.find.results;
        let current = results.iter().position(|(x, y)| *x == a && *y == b);
        let rects = |x: &Pos, y: &Pos| -> Vec<PageRect> {
            layout
                .selection_rects(&s.doc, x, y, hint)
                .into_iter()
                .map(|(page, r)| PageRect { page: page_index(page), x: r.x, y: r.y, width: r.w, height: r.h })
                .collect()
        };
        let matches =
            results.iter().enumerate().take(MAX_FIND_DRAWN).filter(|(i, _)| Some(*i) != current).flat_map(|(_, (x, y))| rects(x, y)).collect();
        let current_rects = current.and_then(|i| results.get(i)).map(|(x, y)| rects(x, y)).unwrap_or_default();
        FindView {
            count: u32::try_from(results.len()).unwrap_or(u32::MAX),
            current: current.and_then(|i| u32::try_from(i).ok()),
            matches,
            current_rects,
        }
    }

    /// Search again as Find's text or options change (`params` as `edit.find` takes them): from
    /// the start of the selected match, so the match being typed stays the selected one.
    pub fn find_again(&self, params: String) -> Result<FindView, MobileError> {
        let params: Value = serde_json::from_str(&params).map_err(|e| MobileError::Command(format!("edit.find: parameters are not JSON: {e}")))?;
        {
            let mut s = self.lock();
            let (a, b) = s.sel.ordered();
            let (a, b) = (a.clone(), b.clone());
            if s.find.results.iter().any(|(x, y)| *x == a && *y == b) {
                s.sel = wordcraft_engine::Selection::caret(a);
            }
            Self::run(&mut s, "edit.find", params)?;
        }
        Ok(self.find_view())
    }

    /// The link the caret is in (or the selection lies in), if any.
    pub fn link_here(&self) -> Option<LinkHere> {
        let s = self.lock();
        let (url, a, b) = link_span(&s)?;
        let p = s.doc.para_at(&s.sel.focus)?;
        let text = p.text.get(a..b).unwrap_or("").chars().filter(|c| *c != wordcraft_engine::doc::para::OBJ).collect();
        Some(LinkHere { url, text })
    }

    /// Select the whole link the caret is in; whether there was one.
    pub fn select_link(&self) -> bool {
        let mut s = self.lock();
        let Some((_, a, b)) = link_span(&s) else { return false };
        let f = s.sel.focus.clone();
        s.sel = wordcraft_engine::Selection { anchor: Pos { off: a, ..f.clone() }, focus: Pos { off: b, ..f } };
        true
    }

    /// Forget Find's matches (the bar closed).
    pub fn clear_find(&self) {
        self.lock().find.results.clear();
    }

    /// The Styles list as the phone app shows it: the document's styles that aren't hidden (or
    /// are used), the recommended built-ins it lacks (one is added when applied), and Heading n
    /// once Heading n-1 shows; all by priority (none counts as 0), then name, each with its look.
    pub fn style_looks(&self) -> Vec<StyleLook> {
        use wordcraft_engine::doc::props::{CharProps, ParaProps, TextColor, Underline};
        use wordcraft_engine::doc::styles::{Style, StyleKind, StyleSheet, heading_level};
        let s = self.lock();
        let doc = &s.doc;
        let builtin = StyleSheet::builtin();
        // the paragraph and character styles the body uses: a hidden style shows once used
        let mut used = std::collections::HashSet::new();
        for path in doc.para_paths(wordcraft_engine::doc::StoryRef::Body).into_iter().take(100_000) {
            if let Some(p) = doc.para(wordcraft_engine::doc::StoryRef::Body, &path) {
                used.extend(p.props.style.clone());
                used.extend(p.run_ranges().filter_map(|(_, c)| c.style.clone()));
            }
        }
        let look = |sheet: &StyleSheet, st: &wordcraft_engine::doc::styles::Style| {
            let character = st.kind == StyleKind::Character;
            let c = if character {
                sheet.resolve_char(None, &CharProps { style: Some(st.id.clone()), ..CharProps::default() })
            } else {
                sheet.resolve_char(Some(&st.id), &CharProps::default())
            };
            let indent =
                if character { 0.0 } else { sheet.resolve_para(&ParaProps { style: Some(st.id.clone()), ..ParaProps::default() }).indent_left };
            StyleLook {
                id: st.id.clone(),
                name: style_display_name(&st.name),
                character,
                font: c.font,
                size: if c.size.is_finite() { c.size.clamp(1.0, 400.0) } else { 11.0 },
                bold: c.bold,
                italic: c.italic,
                underline: c.underline != Underline::None,
                small_caps: c.small_caps,
                color: match c.color {
                    TextColor::Rgb(rgb) => Some(rgb.hex()),
                    TextColor::Auto => None,
                },
                indent: if indent.is_finite() { indent.clamp(0.0, 400.0) } else { 0.0 },
            }
        };
        // shown by its flags (a hidden Heading n beside a shown Heading n-1 too), or used, or a
        // heading below one that is used
        let used_heading = |n: u32| doc.styles.find(&format!("Heading {n}")).is_some_and(|st| used.contains(&st.id));
        let shown = |st: &Style| {
            doc.styles.shown_in_lists(st) || used.contains(&st.id) || heading_level(&st.name).is_some_and(|n| n > 1 && used_heading(n - 1))
        };
        let mut list: Vec<(u32, StyleLook)> = doc
            .styles
            .styles
            .iter()
            .filter(|st| matches!(st.kind, StyleKind::Paragraph | StyleKind::Character))
            .filter(|st| shown(st))
            .map(|st| (st.priority.unwrap_or(0), look(&doc.styles, st)))
            .collect();
        for name in RECOMMENDED_STYLES {
            if doc.styles.find(name).is_some() {
                continue;
            }
            // a built-in the document lacks shows as in a new document, a lower heading once the
            // one above it shows or is used
            let revealed = heading_level(name).is_some_and(|n| {
                n > 1 && doc.styles.find(&format!("Heading {}", n - 1)).map_or(n == 2, |above| !above.hidden || used.contains(&above.id))
            });
            if let Some(st) = builtin.find(name).filter(|st| revealed || builtin.shown_in_lists(st)) {
                list.push((st.priority.unwrap_or(0), look(&builtin, st)));
            }
        }
        list.sort_by_cached_key(|(priority, l)| (*priority, l.name.to_lowercase()));
        list.into_iter().map(|(_, l)| l).collect()
    }

    /// The selected picture's or shape's alt text, for its Alt Text pane; `None` with no object
    /// selected.
    pub fn object_alt(&self) -> Option<ObjectAlt> {
        let s = self.lock();
        let (_, o) = wordcraft_engine::cmd::objects::selected(&s)?;
        let decorative = o.frame().is_some_and(|(_, _, f)| f.alt.decorative);
        Some(ObjectAlt { text: o.alt_text().to_string(), decorative })
    }

    /// The selected chart's type, title, labels, legend and colours; `None` with no chart (or one
    /// from another program, which can't be edited) selected.
    pub fn chart_state(&self) -> Option<ChartState> {
        use wordcraft_engine::doc::chart::LabelPos;
        let s = self.lock();
        let c = wordcraft_engine::cmd::chart::selected_chart(&s)?;
        Some(ChartState {
            kind: c.kind.id().into(),
            family: c.kind.family().id().into(),
            title: match (&c.title, c.title_overlay) {
                (None, _) => "none",
                (Some(_), false) => "above",
                (Some(_), true) => "overlay",
            }
            .into(),
            labels: match (c.data_labels, c.label_pos) {
                (false, _) => "none".into(),
                (true, None) => "default".into(),
                (true, Some(p)) => p.id().into(),
            },
            label_places: LabelPos::choices(c.kind).iter().map(|p| NamedChoice { id: p.id().into(), name: p.label().into() }).collect(),
            legend: c.legend.map_or("none", |p| p.id()).into(),
            palette: c.palette.id(),
        })
    }

    /// A chart gallery's pictures, `width_px` wide, of the selected chart as each choice would
    /// make it: `type:<family>` the family's types, `layout` the quick layouts. Empty with no
    /// editable chart selected.
    pub fn chart_gallery(&self, which: String, width_px: u32) -> Vec<GalleryImage> {
        let s = self.lock();
        let Some(spec) = wordcraft_engine::cmd::chart::selected_chart(&s) else { return Vec::new() };
        let (w, h) = CHART_THUMB;
        let scale = (width_px.clamp(16, 2000) as f32 / w).clamp(0.05, 8.0);
        let opts = render_options(&s);
        wordcraft_engine::cmd::chart::gallery(&spec, &which)
            .into_iter()
            .map(|(id, v)| {
                let g = wordcraft_engine::cmd::chart::chart_graphic(v, &s.doc.settings.theme_colors, w, h);
                let draws = wordcraft_engine::layout::display::graphic_display(&s.doc, &g, w, h);
                let r = render::render_items(&s.doc, &draws, 0.0, 0.0, w, h, scale, &opts);
                GalleryImage { id, image: PageImage { width: r.width, height: r.height, rgba: r.pixels } }
            })
            .collect()
    }

    /// The Picture Styles gallery: each style (its id) drawn on a sample picture, `width_px` wide.
    pub fn picture_style_gallery(&self, width_px: u32) -> Vec<GalleryImage> {
        use wordcraft_engine::cmd::objects::{PICTURE_STYLES, picture_style, sample_picture_png};
        let s = self.lock();
        let opts = render_options(&s);
        let (w, h) = PICTURE_THUMB;
        let scale = (width_px.clamp(16, 2000) as f32 / w).clamp(0.05, 8.0);
        let mut doc = Document::new();
        let media = doc.add_media(sample_picture_png(), "png");
        let [x, y, pw, ph] = PICTURE_THUMB_FRAME;
        PICTURE_STYLES
            .iter()
            .filter_map(|id| {
                let (framing, effects) = picture_style(id)?;
                let o = wordcraft_engine::doc::para::InlineObject::Image {
                    media: media.clone(),
                    w: pw,
                    h: ph,
                    alt: String::new(),
                    float: Default::default(),
                    crop: [0.0; 4],
                    ole: None,
                    effects,
                    framing,
                    svg: None,
                };
                let draws = wordcraft_engine::layout::display::drawing_display(&o, x, y, pw, ph, &Default::default());
                let r = render::render_items(&doc, &draws, 0.0, 0.0, w, h, scale, &opts);
                Some(GalleryImage { id: id.to_string(), image: PageImage { width: r.width, height: r.height, rgba: r.pixels } })
            })
            .collect()
    }

    /// The chart palettes in the document's theme, for the Color page: the four colourful ones,
    /// then the thirteen monochromatic ones.
    pub fn chart_palettes(&self) -> Vec<ChartPaletteView> {
        use wordcraft_engine::doc::chart::ChartPalette;
        let s = self.lock();
        let theme = &s.doc.settings.theme_colors;
        ChartPalette::ALL
            .into_iter()
            .map(|p| ChartPaletteView {
                id: p.id(),
                colors: wordcraft_engine::cmd::chart::palette_colors(p, theme).iter().map(|c| c.hex()).collect(),
            })
            .collect()
    }

    /// The selected picture's crop: the parts of its source trimmed off the left, top, right and
    /// bottom, as fractions; `None` with no picture selected.
    pub fn picture_crop(&self) -> Option<Vec<f32>> {
        let s = self.lock();
        match wordcraft_engine::cmd::objects::selected(&s)? {
            (_, wordcraft_engine::doc::para::InlineObject::Image { crop, .. }) => Some(crop.to_vec()),
            _ => None,
        }
    }

    /// The document's theme fonts: the one for headings, then the one for body text.
    pub fn theme_fonts(&self) -> Vec<String> {
        let s = self.lock();
        vec![s.doc.settings.major_font.clone(), s.doc.settings.minor_font.clone()]
    }

    /// `mobile` while the document is reflowed (Web Layout), else `print`.
    pub fn view_mode(&self) -> String {
        if self.lock().view.mode == wordcraft_engine::layout::ViewMode::Web { "mobile".into() } else { "print".into() }
    }

    /// The formatting at the selection (the engine's `format.state`) and the caret paragraph's
    /// alignment, direction and list, read as the desktop ribbon reads them.
    pub fn format_state(&self) -> FormatState {
        let mut s = self.lock();
        let v = s.run("format.state", &json!({})).unwrap_or(Value::Null);
        let text = |k: &str| v.get(k).and_then(Value::as_str).map(str::to_string);
        let flag = |k: &str| v.get(k).and_then(Value::as_bool).unwrap_or(false);
        let rp = s.doc.para_at(&s.sel.focus).map(|p| s.doc.styles.resolve_para(&p.props));
        let align = rp.as_ref().map(|r| r.align.visual(r.bidi)).unwrap_or_default();
        let lists = wordcraft_engine::cmd::para::list_buttons(&s.doc, rp.as_ref().and_then(|r| r.numbering));
        FormatState {
            font: text("font"),
            size: v.get("size").and_then(Value::as_f64).map(|n| n as f32),
            bold: flag("bold"),
            italic: flag("italic"),
            underline: flag("underline"),
            strikethrough: flag("strike"),
            subscript: flag("subscript"),
            superscript: flag("superscript"),
            color: text("color"),
            highlight: text("highlight"),
            style_name: text("styleName"),
            align: align_name(align).to_string(),
            rtl: rp.as_ref().is_some_and(|r| r.bidi),
            bullets: lists.bullets,
            numbering: lists.numbering,
            multilevel: lists.multilevel,
            line_spacing: rp.as_ref().map(|r| spacing_label(r.line_spacing)).unwrap_or_else(|| "1.0".into()),
            space_before: rp.as_ref().map_or(0.0, |r| r.space_before),
            space_after: rp.as_ref().map_or(0.0, |r| r.space_after),
            first_line: rp.as_ref().map_or(0.0, |r| r.indent_first),
            in_table: s.sel.focus.path.0.len() >= 4,
            object: wordcraft_engine::cmd::objects::object_selection(&s).map(|(_, o)| {
                use wordcraft_engine::doc::graphic::GraphicKind;
                use wordcraft_engine::doc::para::InlineObject;
                match o {
                    InlineObject::Image { .. } => "picture",
                    InlineObject::Graphic { graphic, .. } => match graphic.kind {
                        GraphicKind::Chart => "chart",
                        GraphicKind::Diagram => "smartArt",
                        GraphicKind::Ink => "graphic",
                    },
                    _ => "shape",
                }
                .to_string()
            }),
            object_inline: wordcraft_engine::cmd::objects::object_selection(&s)
                .is_some_and(|(_, o)| o.frame().is_some_and(|(_, _, f)| f.wrap == wordcraft_engine::doc::para::Wrap::Inline)),
            object_icon: matches!(
                wordcraft_engine::cmd::objects::object_selection(&s),
                Some((_, wordcraft_engine::doc::para::InlineObject::Image { svg: Some(_), .. }))
            ),
            story: story_name(&s).to_string(),
            cell_valign: s.sel.focus.path.cell().and_then(|(t, r, c)| {
                use wordcraft_engine::doc::props::VAlign;
                let cell = s.doc.table(s.sel.focus.story, &t)?.rows.get(r)?.cells.get(c)?;
                Some(
                    match cell.props.valign {
                        Some(VAlign::Center) => "middle",
                        Some(VAlign::Bottom) => "bottom",
                        _ => "top",
                    }
                    .to_string(),
                )
            }),
            note_here: s.doc.para_at(&s.sel.focus).and_then(|p| {
                use wordcraft_engine::doc::para::{InlineObject, NoteKind, OBJ};
                let at = s.sel.focus.off;
                [at, at.saturating_sub(OBJ.len_utf8())].into_iter().find_map(|o| match p.object_at(o) {
                    Some(InlineObject::NoteRef { kind: NoteKind::Footnote, .. }) => Some("footnote".to_string()),
                    Some(InlineObject::NoteRef { kind: NoteKind::Endnote, .. }) => Some("endnote".to_string()),
                    _ => None,
                })
            }),
        }
    }

    /// The page setup of the section the caret is in.
    pub fn page_setup(&self) -> PageSetup {
        let mut s = self.lock();
        let layout = s.layout();
        let page = layout.caret_on(&s.sel.focus, s.page_hint).map_or(0, |c| c.page);
        let section = layout.pages.get(page).map_or(0, |p| p.section);
        let sections = s.doc.sections();
        let props = sections.get(section).or_else(|| sections.last()).map(|(_, p)| (*p).clone()).unwrap_or_default();
        PageSetup {
            width: props.page_w,
            height: props.page_h,
            landscape: props.landscape,
            margin_top: props.margin_top,
            margin_bottom: props.margin_bottom,
            margin_left: props.margin_left,
            margin_right: props.margin_right,
        }
    }

    /// Whether changes are tracked and shown, and how many comments and changes there are.
    pub fn review_state(&self) -> ReviewState {
        let s = self.lock();
        let count = |n: usize| u32::try_from(n).unwrap_or(u32::MAX);
        ReviewState {
            track_changes: s.doc.settings.track_changes,
            show_markup: s.view.show_markup,
            markup: s.view.markup_view.id().to_string(),
            comments: count(s.doc.comments.len()),
            revisions: count(s.doc.revisions.len()),
            comment_here: wordcraft_engine::cmd::review::comment_at_caret(&s).is_some(),
        }
    }

    /// The colours the colour menus offer (the same grid the desktop's colour menus draw).
    pub fn color_choices(&self) -> ColorChoices {
        use wordcraft_engine::doc::props::{Highlight, Rgb};
        let s = self.lock();
        let swatch = |c: Rgb, label: String| Swatch { name: c.hex(), hex: c.hex(), label };
        // the theme's ten colours in the desktop's order, then five lighter and darker shades of
        // each: the colour's lightness moved towards white or black, its hue and saturation kept
        let base = s.doc.settings.theme_colors.iter().take(10).copied().collect::<Vec<_>>();
        let order = [1usize, 0, 3, 2, 4, 5, 6, 7, 8, 9];
        let colours: Vec<Rgb> = order.iter().filter_map(|&i| base.get(i).copied()).collect();
        let columns: Vec<[Rgb; 6]> = colours.iter().map(|&c| shades(c)).collect();
        // named by their place in the theme (bg1, tx1, bg2, tx2, accents), as the file format does
        const SLOTS: [&str; 10] =
            ["Background 1", "Text 1", "Background 2", "Text 2", "Accent 1", "Accent 2", "Accent 3", "Accent 4", "Accent 5", "Accent 6"];
        let theme = (0..6)
            .map(|row| {
                columns
                    .iter()
                    .zip(colours.iter().zip(SLOTS))
                    .map(|(col, (&base, slot))| {
                        let shade = shade_names(base).get(row).copied().unwrap_or("");
                        swatch(col[row], if shade.is_empty() { slot.to_string() } else { format!("{slot}, {shade}") })
                    })
                    .collect()
            })
            .filter(|row: &Vec<Swatch>| !row.is_empty())
            .collect();
        let standard = [
            ("C00000", "Dark Red"),
            ("FF0000", "Red"),
            ("FFC000", "Orange"),
            ("FFFF00", "Yellow"),
            ("92D050", "Light Green"),
            ("00B050", "Green"),
            ("00B0F0", "Light Blue"),
            ("0070C0", "Blue"),
            ("002060", "Dark Blue"),
            ("7030A0", "Purple"),
        ]
        .iter()
        .filter_map(|(h, label)| Some(swatch(Rgb::parse(h)?, label.to_string())))
        .collect();
        // the highlight colours, by their OOXML names: `format.highlight` matches those first, so
        // they are unambiguous (its "green" is the bright green; the darker one is "darkGreen")
        let highlights = Highlight::ALL
            .iter()
            .filter(|h| !matches!(h, Highlight::None | Highlight::White))
            .filter_map(|h| Some(Swatch { name: h.ooxml().to_string(), hex: h.rgb()?.hex(), label: highlight_label(*h).to_string() }))
            .collect();
        ColorChoices { theme, standard, highlights }
    }

    /// Read Aloud: the body's sentences from the caret (from the start when `from_start`), in
    /// reading order, citations left out. The app speaks them one by one.
    pub fn read_aloud_sentences(&self, from_start: bool) -> Vec<String> {
        let s = self.lock();
        let from = if from_start { Pos::body(0, 0) } else { s.sel.ordered().0 };
        let found = speech::sentences(&s.doc, &from, None, true);
        let texts = found.iter().map(|u| u.text.clone()).collect();
        *self.reading.lock().unwrap_or_else(PoisonError::into_inner) = found;
        texts
    }

    /// Where each comment thread is anchored in the body: the line its anchor starts on (page,
    /// x, top, height), for the marks Mobile View shows beside commented lines. Replies, and
    /// comments whose anchor is gone, have none.
    pub fn comment_marks(&self) -> Vec<PageRect> {
        let mut s = self.lock();
        let anchors: Vec<Pos> = wordcraft_engine::cmd::review::comment_list(&s)
            .into_iter()
            .filter(|(id, _)| s.doc.comments.get(id).is_some_and(|c| c.parent.is_none()))
            .filter_map(|(_, pos)| pos)
            .collect();
        if anchors.is_empty() {
            return Vec::new();
        }
        let layout = s.layout();
        anchors
            .iter()
            .filter_map(|p| layout.caret(p))
            .map(|c| PageRect { page: page_index(c.page), x: c.x, y: c.top, width: 0.0, height: c.height })
            .collect()
    }

    /// The rectangles of sentence `index` of the last Read Aloud list, to highlight it while it
    /// is spoken.
    pub fn read_aloud_rects(&self, index: u32) -> Vec<PageRect> {
        let Some(u) = self.reading.lock().unwrap_or_else(PoisonError::into_inner).get(index as usize).cloned() else { return Vec::new() };
        let mut s = self.lock();
        let layout = s.layout();
        layout
            .selection_rects(&s.doc, &u.start, &u.end, s.page_hint)
            .into_iter()
            .map(|(page, r)| PageRect { page: page_index(page), x: r.x, y: r.y, width: r.w, height: r.h })
            .collect()
    }

    /// The rectangles of word `word` of sentence `index` of the last Read Aloud list (counting
    /// the words as spoken: runs between spaces with a letter or digit), to highlight it while it
    /// is said.
    pub fn read_aloud_word_rects(&self, index: u32, word: u32) -> Vec<PageRect> {
        let Some(u) = self.reading.lock().unwrap_or_else(PoisonError::into_inner).get(index as usize).cloned() else { return Vec::new() };
        let mut s = self.lock();
        let Some((a, b)) = speech::word_span(&s.doc, &u, word as usize) else { return Vec::new() };
        let layout = s.layout();
        layout
            .selection_rects(&s.doc, &a, &b, s.page_hint)
            .into_iter()
            .map(|(page, r)| PageRect { page: page_index(page), x: r.x, y: r.y, width: r.w, height: r.h })
            .collect()
    }

    /// What the engine asked of the app since the last call; clears them.
    pub fn take_events(&self) -> EngineEvents {
        let mut s = self.lock();
        let requests = std::mem::take(&mut s.ui_requests).into_iter().map(|v| v.to_string()).collect();
        let status = std::mem::take(&mut s.status);
        EngineEvents { requests, status: (!status.is_empty()).then_some(status) }
    }

    /// A copy of the document as a file of the format `name`'s extension names, for sharing or
    /// printing: unlike [`MobileSession::save_bytes`] it leaves the document's saved state alone.
    pub fn export_bytes(&self, name: String) -> Result<Vec<u8>, MobileError> {
        let s = self.lock();
        let opts = file::export_options(&s, &json!({}));
        let password = s.password.as_ref().map(|p| p.as_str().to_string());
        io::save_bytes_with(&name, &s.doc, password.as_deref(), &opts).map_err(MobileError::Save)
    }

    /// The document as a file of the format `name`'s extension names (docx, pdf, odt, rtf, txt…),
    /// for the app to write where the user keeps it. Saving as a format that keeps everything
    /// marks the document saved.
    pub fn save_bytes(&self, name: String) -> Result<Vec<u8>, MobileError> {
        let mut s = self.lock();
        s.stamp_save();
        let opts = file::export_options(&s, &json!({}));
        let password = s.password.as_ref().map(|p| p.as_str().to_string());
        let bytes = io::save_bytes_with(&name, &s.doc, password.as_deref(), &opts).map_err(MobileError::Save)?;
        if keeps_everything(&name) {
            s.dirty = false;
        }
        Ok(bytes)
    }
}

/// The document's revision, with the proofing choices that change what is drawn without an edit
/// (spelling marks, grammar marks).
fn drawn_revision(s: &Session) -> u64 {
    use std::hash::{Hash, Hasher};
    let mut h = std::collections::hash_map::DefaultHasher::new();
    (s.rev(), s.view.proofing, s.prefs.mark_grammar).hash(&mut h);
    h.finish()
}

/// The document's state for [`DocumentInfo`].
fn info(s: &mut Session) -> DocumentInfo {
    let layout = s.layout();
    DocumentInfo {
        document_id: s.document_id(),
        revision: drawn_revision(s),
        pages: layout.pages.iter().map(|p| PageSize { width: p.w, height: p.h, markup: p.markup }).collect(),
        dirty: s.dirty,
        can_undo: s.can_undo(),
        can_redo: s.can_redo(),
        undo_label: s.undo_label().map(str::to_string),
        redo_label: s.redo_label().map(str::to_string),
    }
}

/// The link around the selection's focus in its paragraph: its target and its byte range (the
/// neighbouring runs with the same target). A collapsed caret at either end of the link counts
/// as in it; a selection must lie inside it.
fn link_span(s: &Session) -> Option<(String, usize, usize)> {
    let (a, b) = s.sel.ordered();
    if a.story != b.story || a.path != b.path {
        return None;
    }
    let p = s.doc.para_at(&s.sel.focus)?;
    let runs: Vec<(std::ops::Range<usize>, Option<&String>)> = p.run_ranges().map(|(r, c)| (r, c.link.as_ref())).collect();
    let (lo, hi) = (a.off, b.off);
    let i = runs.iter().position(|(r, l)| l.is_some() && r.start <= lo && hi <= r.end && (r.start < hi || lo < r.end))?;
    let url = runs.get(i)?.1?.clone();
    let same = |k: usize| runs.get(k).is_some_and(|(_, l)| l.is_some_and(|l| *l == url));
    let (mut first, mut last) = (i, i);
    while first > 0 && same(first - 1) {
        first -= 1;
    }
    while same(last + 1) {
        last += 1;
    }
    Some((url, runs.get(first)?.0.start, runs.get(last)?.0.end))
}

/// The names of a theme colour's five shades ([`shades`]), after an empty one for the colour.
fn shade_names(c: wordcraft_engine::doc::props::Rgb) -> [&'static str; 6] {
    let (_, _, l) = to_hsl(c);
    if l < 0.2 {
        ["", "Lighter 90%", "Lighter 75%", "Lighter 50%", "Lighter 25%", "Lighter 10%"]
    } else if l > 0.8 {
        ["", "Darker 10%", "Darker 25%", "Darker 50%", "Darker 75%", "Darker 90%"]
    } else {
        ["", "Lighter 80%", "Lighter 60%", "Lighter 40%", "Darker 25%", "Darker 50%"]
    }
}

/// A highlight colour as people call it.
fn highlight_label(h: wordcraft_engine::doc::props::Highlight) -> &'static str {
    use wordcraft_engine::doc::props::Highlight as H;
    match h {
        H::Yellow => "Yellow",
        H::BrightGreen => "Bright Green",
        H::Turquoise => "Turquoise",
        H::Pink => "Pink",
        H::Blue => "Blue",
        H::Red => "Red",
        H::DarkBlue => "Dark Blue",
        H::Teal => "Teal",
        H::Green => "Green",
        H::Violet => "Violet",
        H::DarkRed => "Dark Red",
        H::DarkYellow => "Dark Yellow",
        H::Gray50 => "Gray",
        H::Gray25 => "Light Gray",
        H::Black => "Black",
        H::White => "White",
        H::None => "No Color",
    }
}

/// A theme colour's column in the colour menus: the colour, then five shades. How far each moves
/// depends on how light the colour is: a dark one gets lighter versions (90, 75, 50, 25 and 10%
/// of the way to white), a light one darker ones (10 to 90% of the way to black), any other two
/// darker after three lighter (80, 60, 40% lighter; 25, 50% darker).
fn shades(c: wordcraft_engine::doc::props::Rgb) -> [wordcraft_engine::doc::props::Rgb; 6] {
    let (h, sat, l) = to_hsl(c);
    let lighter = |k: f64| from_hsl(h, sat, l + (1.0 - l) * k);
    let darker = |k: f64| from_hsl(h, sat, l * (1.0 - k));
    if l < 0.2 {
        [c, lighter(0.9), lighter(0.75), lighter(0.5), lighter(0.25), lighter(0.1)]
    } else if l > 0.8 {
        [c, darker(0.1), darker(0.25), darker(0.5), darker(0.75), darker(0.9)]
    } else {
        [c, lighter(0.8), lighter(0.6), lighter(0.4), darker(0.25), darker(0.5)]
    }
}

/// Hue (0–1), saturation and lightness of a colour.
fn to_hsl(c: wordcraft_engine::doc::props::Rgb) -> (f64, f64, f64) {
    let (r, g, b) = (f64::from(c.0) / 255.0, f64::from(c.1) / 255.0, f64::from(c.2) / 255.0);
    let (max, min) = (r.max(g).max(b), r.min(g).min(b));
    let l = (max + min) / 2.0;
    let d = max - min;
    if d <= f64::EPSILON {
        return (0.0, 0.0, l);
    }
    let s = if l > 0.5 { d / (2.0 - max - min) } else { d / (max + min) };
    let h = if max == r {
        ((g - b) / d).rem_euclid(6.0)
    } else if max == g {
        (b - r) / d + 2.0
    } else {
        (r - g) / d + 4.0
    } / 6.0;
    (h, s, l)
}

fn from_hsl(h: f64, s: f64, l: f64) -> wordcraft_engine::doc::props::Rgb {
    let l = l.clamp(0.0, 1.0);
    let c = (1.0 - (2.0 * l - 1.0).abs()) * s.clamp(0.0, 1.0);
    let hp = h.rem_euclid(1.0) * 6.0;
    let x = c * (1.0 - (hp.rem_euclid(2.0) - 1.0).abs());
    let (r, g, b) = match hp as u32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    let m = l - c / 2.0;
    // cut down, not rounded, as the colour menus are
    let byte = |v: f64| ((v + m) * 255.0 + 1e-6).clamp(0.0, 255.0) as u8;
    wordcraft_engine::doc::props::Rgb(byte(r), byte(g), byte(b))
}

/// How the editor draws pages: as the desktop does on screen (formatting marks, markup and the
/// dark page as the view has them; headers and footers dimmed while the body is edited).
fn render_options(s: &Session) -> RenderOptions {
    let mut opts = RenderOptions::default();
    opts.display.marks = s.view.marks;
    opts.display.always = s.prefs.marks;
    opts.display.placeholders = true;
    opts.display.markup = s.view.show_markup;
    opts.display.simple_markup = s.view.markup_view == wordcraft_engine::MarkupView::Simple;
    opts.display.hide_ink = s.view.hide_ink;
    opts.display.revisions = s.prefs.markup.clone();
    opts.dark = s.view.dark_mode;
    opts.dark_paper = DARK_PAPER;
    opts
}

/// Run a command only to look (is there a control at the caret?): when it fails, its message
/// doesn't become the status the app shows next.
fn probe(s: &mut Session, id: &str, params: &Value) -> Option<Value> {
    let status = std::mem::take(&mut s.status);
    let r = s.run(id, params);
    s.status = status;
    r.ok()
}

fn open_error(e: &CmdError) -> MobileError {
    let msg = e.to_string();
    if io::needs_password(&msg) {
        MobileError::NeedsPassword
    } else if io::wrong_password(&msg) {
        MobileError::WrongPassword
    } else {
        MobileError::Open(msg)
    }
}

/// Which kind of story the caret is in.
fn story_name(s: &Session) -> &'static str {
    use wordcraft_engine::doc::{PartKind, StoryRef};
    match s.sel.focus.story {
        StoryRef::Body => "body",
        StoryRef::Part(id) => match s.doc.parts.get(&id).map(|p| p.kind) {
            Some(PartKind::Header) => "header",
            Some(PartKind::Footer) => "footer",
            Some(PartKind::Footnote) => "footnote",
            Some(PartKind::Endnote) => "endnote",
            Some(PartKind::Comment) => "comment",
            Some(PartKind::TextBox) => "textBox",
            None => "body",
        },
    }
}

/// A line spacing as the palette shows it: `1.0`, `1.08`, `At least 12 pt`, `Exactly 12 pt`.
fn spacing_label(l: wordcraft_engine::doc::props::LineSpacing) -> String {
    use wordcraft_engine::doc::props::LineSpacing;
    let num = |v: f32| {
        let s = format!("{:.2}", v);
        let s = s.trim_end_matches('0');
        if s.ends_with('.') { format!("{s}0") } else { s.to_string() }
    };
    match l {
        LineSpacing::Multiple(m) => num(m),
        LineSpacing::AtLeast(p) => format!("At least {} pt", num(p).trim_end_matches(".0")),
        LineSpacing::Exactly(p) => format!("Exactly {} pt", num(p).trim_end_matches(".0")),
    }
}

fn align_name(a: wordcraft_engine::doc::props::Align) -> &'static str {
    use wordcraft_engine::doc::props::Align;
    match a {
        Align::Left => "left",
        Align::Center => "center",
        Align::Right => "right",
        Align::Justify => "justify",
        Align::Distribute => "distribute",
    }
}

fn clamp_scale(scale: f32) -> f32 {
    if scale.is_finite() { scale.clamp(MIN_SCALE, MAX_SCALE) } else { 1.0 }
}

fn page_index(page: usize) -> u32 {
    u32::try_from(page).unwrap_or(u32::MAX)
}

/// The equation command a key's command (`caret.left`, `text.tab`…) is while an equation is
/// being edited, as the desktop's keys are; `None` when none is being edited, or for other
/// commands.
fn equation_key(s: &Session, id: &str) -> Option<(&'static str, Value)> {
    s.math.as_ref()?;
    let dir = |d: &str| json!({ "dir": d });
    Some(match id {
        "caret.left" => ("equation.move", dir("left")),
        "caret.right" => ("equation.move", dir("right")),
        "caret.up" => ("equation.move", dir("up")),
        "caret.down" => ("equation.move", dir("down")),
        "caret.home" => ("equation.move", dir("home")),
        "caret.end" => ("equation.move", dir("end")),
        "text.tab" => ("equation.move", dir("next")),
        "text.backTab" => ("equation.move", dir("prev")),
        "text.backspace" => ("equation.backspace", json!({})),
        "text.delete" => ("equation.delete", json!({})),
        "text.newParagraph" | "text.lineBreak" => ("equation.enter", json!({})),
        _ => return None,
    })
}

fn caret_box(c: Caret) -> CaretBox {
    CaretBox { page: page_index(c.page), x: c.x, top: c.top, height: c.height, width: c.width }
}

/// Formats that keep everything in the document (the desktop's rule): saving as one of them
/// leaves nothing unsaved.
fn keeps_everything(name: &str) -> bool {
    let ext = std::path::Path::new(name).extension().map(|e| e.to_string_lossy().to_ascii_lowercase()).unwrap_or_default();
    matches!(ext.as_str(), "docx" | "docm" | "dotx" | "dotm" | "odt" | "rtf" | "json" | "xml")
}

/// The end of `s`, at most `units` UTF-16 code units long, never splitting a character.
fn last_utf16(s: &str, units: usize) -> String {
    let mut n = 0;
    let mut start = s.len();
    for (i, c) in s.char_indices().rev() {
        n += c.len_utf16();
        if n > units {
            break;
        }
        start = i;
    }
    s.get(start..).unwrap_or_default().to_string()
}

/// The start of `s`, at most `units` UTF-16 code units long, never splitting a character.
fn first_utf16(s: &str, units: usize) -> String {
    let mut n = 0;
    let mut end = 0;
    for (i, c) in s.char_indices() {
        n += c.len_utf16();
        if n > units {
            break;
        }
        end = i + c.len_utf8();
    }
    s.get(..end).unwrap_or_default().to_string()
}
